WITH valid AS (SELECT *, UPPER(segment) AS segment_upper, CONCAT_WS('-', name, country) AS name_country_key FROM customers WHERE signup_date > TO_DATE('2023-05-17')), deduped AS (SELECT id, name, email, city, segment, signup_date, credit_limit, segment_upper, name_country_key FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY segment ORDER BY signup_date NULLS LAST, id) AS dedup_rank FROM valid) t WHERE dedup_rank = 1), with_latest AS (SELECT s.id, s.segment, s.segment_upper, top1.order_amount FROM deduped s JOIN LATERAL (SELECT c.amount AS order_amount FROM orders c WHERE c.customer_id = s.id ORDER BY c.shipping_fee DESC, c.id DESC LIMIT 1) top1 ON TRUE), kept AS (SELECT s.* FROM with_latest s WHERE EXISTS (SELECT 1 FROM subscriptions ch WHERE ch.customer_id = s.id AND ch.status = 'EXPIRED')), remaining_keys AS (SELECT id FROM kept EXCEPT SELECT id FROM customers WHERE email LIKE '%@GMAIL.COM'), verified AS (SELECT s.* FROM kept s JOIN remaining_keys k ON s.id = k.id) SELECT segment, ROUND(SUM(order_amount) / NULLIF(COUNT(CASE WHEN segment = 'SMB' THEN 1 END), 0), 2) AS order_amount_per_smb, COUNT(DISTINCT id) AS distinct_ids, COUNT(DISTINCT id) AS distinct_ids_2 FROM verified GROUP BY segment
